import {guidedLessons,guidedTermLists,basicTermDefinitions,bondLessonExample} from './lesson-content.js';
import {readGuided,writeGuided,startGuided,finishGuided,nextGuided} from './guided-progress.js';
import {generate,parseNumber,isCorrect,bondPrice} from './calculations.js';
import {chapterConnections,renderConnections} from './connections.js';
import {renderCalculator,calculatorExampleKey} from './calculator.js';
export function shortTermHelp(text,label='Explain formula terms'){
 const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 return text?`<details class="term-help"><summary class="button">${safe(label)}</summary><div class="terms-box">${String(text).split(';').map(x=>`<p>${safe(x.trim())}</p>`).join('')}</div></details>`:'';
}
export function renderNumberWork(example,escape,{withCalculator=true}={}){
 return `<section class="number-work"><span class="eyebrow">WORKED EXAMPLE</span><p class="small muted">These are chosen example amounts and rates, not current market quotes.</p>${example.readingGuide?`<p class="calculation-reading">${escape(example.readingGuide)}</p>`:''}<dl class="example-inputs">${example.givens.map(([label,value])=>`<div><dt>${escape(label)}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl>${withCalculator?renderCalculator(calculatorExampleKey(example)):''}<div class="formula">${escape(example.formula)}</div>${shortTermHelp(example.symbols)}<ol class="calculation-steps">${example.steps.map(s=>`<li>${escape(s)}</li>`).join('')}</ol><p class="example-result"><span>${escape(example.unitLabel||'Calculated result')}</span><strong>${escape(example.answerText)}</strong></p>${example.resultMeaning?`<p class="result-meaning">${escape(example.resultMeaning)}</p>`:''}</section>`;
}
export function mountGuidedCourse(root,route,{data,escape:escapeGuide,notify}){
 const loaded=readGuided(),p=loaded.progress,e=escapeGuide;
 let lastSaveOk=true;
 const priceLabel=value=>'$'+value.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
 const persist=()=>{lastSaveOk=writeGuided(p,loaded.blocked);if(!lastSaveOk&&!loaded.blocked)notify('This browser could not save your lesson progress.');return lastSaveOk;};
 const warning=loaded.warning?`<p class="errorbanner">${e(loaded.warning)}</p>`:'';
 const topic=id=>data.topics.find(t=>t.id===id),card=id=>data.cards.find(c=>c.id===id);
 const dateGuide=t=>new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});
 const completeCount=guidedLessons.filter(l=>p.lessons[l.id]?.completedAt).length;
 const open=id=>{startGuided(p,id);persist();location.hash='lesson/'+id;};
 const lesson=guidedLessons.find(l=>route==='lesson/'+l.id);
 function bindStarts(){root.querySelectorAll('[data-guide-start]').forEach(b=>b.onclick=()=>open(b.dataset.guideStart));}
 if(route==='today'){
  const next=nextGuided(p),chosen=guidedLessons.find(l=>l.id===next?.id),due=guidedLessons.filter(l=>p.lessons[l.id]?.completedAt&&p.lessons[l.id].due<=Date.now()).length;
  root.innerHTML=warning+`<section class="hero guided-home"><div><span class="pill">Your daily learning desk</span><h1>Finance,<br>in context.</h1><p class="muted">Take the idea step by step. See what the words and numbers mean, then try one question.</p><p class="small muted">Pick up where you left off. Terms and calculations are there when you need them.</p></div><div class="plan"><span class="eyebrow">${next?.kind==='review'?'A SHORT SPACED REVIEW':next?.kind==='continue'?'PICK UP YOUR LESSON':'YOUR NEXT LESSON'}</span><h2>${chosen?e(chosen.title):'You’re caught up.'}</h2><p class="muted">${chosen?e(topic(chosen.topic).title.split(' · ')[1]):'Revisit a chapter whenever you want.'}</p>${chosen?`<button class="primary" data-guide-start="${chosen.id}">${next.kind==='review'?'Review with a reminder':next.kind==='continue'?'Continue lesson':'Start lesson'} →</button>`:'<a class="button primary" href="#lessons">Browse lessons</a>'}<p class="small muted">${completeCount} of ${guidedLessons.length} lessons explored${due?' · '+due+' ready to revisit':''}</p></div></section><div class="guided-home-links"><a class="button" href="#lessons">Browse the course</a><a class="textbutton" href="#progress">See lesson progress</a></div><div class="callout"><p>Read the explanation, then try the application. You can ask for a walkthrough. Afterward, choose whether the idea is clear or needs another look.</p><p class="small muted">One lesson is enough for today. Additional calculations and reference details are optional.</p></div>`;bindStarts();return;
 }
 if(route==='progress'){
  root.innerHTML=warning+`<span class="eyebrow">WHAT YOU’VE EXPLORED</span><h1>Your lesson progress.</h1><p class="muted">${completeCount} of ${guidedLessons.length} lessons completed. This records your practice, not a claim of mastery.</p><div class="bars">${data.topics.map(t=>{const ls=guidedLessons.filter(l=>l.topic===t.id),count=ls.filter(l=>p.lessons[l.id]?.completedAt).length;return `<div class="bar"><a class="link" href="#chapter/${t.id}">${e(t.title.split(' · ')[1])}</a><div class="meter"><span style="width:${count/ls.length*100}%"></span></div><span>${count}/${ls.length}</span></div>`;}).join('')}</div><div class="lesson"><h3>Coming back at useful intervals</h3><p class="small">Clear lessons start with a review in three days, then gradually move farther apart. “Another look” schedules tomorrow. Reviews begin with the situation and one application, with the explanation available on request.</p><p class="small muted">Your earlier card reviews and trial records are preserved. <a class="link" href="#card-progress">View earlier card statistics</a>.</p></div>`;return;
 }
 if(!lesson){
  const chapter=route.startsWith('chapter/')?topic(route.split('/')[1]):null;
  if(chapter){const ls=guidedLessons.filter(l=>l.topic===chapter.id);root.innerHTML=warning+`<a class="back" href="#lessons">← Course</a><h1>${e(chapter.title.split(' · ')[1])}</h1><p class="muted">${e(chapter.subtitle)}</p><div class="guided-list">${ls.map(l=>{const r=p.lessons[l.id];return `<article class="guided-list-item"><div><h3>${e(l.title)}</h3><p class="small muted">${r?.inProgress?'In progress':r?.completedAt?'Explored · next review '+dateGuide(r.due):'Ready to explore'}</p></div><button data-guide-start="${l.id}">${r?.inProgress?'Continue':r?.completedAt?'Revisit':'Start'} →</button></article>`;}).join('')}</div>${renderConnections(chapter.id,e)}`;bindStarts();return;}
  root.innerHTML=warning+`<span class="eyebrow">A COURSE YOU CAN FOLLOW</span><h1>One idea at a time.</h1><p class="muted">${guidedLessons.length} connected lessons cover the course’s ${data.cards.length} concepts. Start with bonds or choose a chapter. Each lesson explains a situation in small sections, with examples and units, then asks one application question.</p><p class="small muted">Every chapter also offers optional Connections &amp; history: an extra idea, a real episode, and links to explore.</p><div class="grid">${data.topics.map(t=>{const ls=guidedLessons.filter(l=>l.topic===t.id),count=ls.filter(l=>p.lessons[l.id]?.completedAt).length;return `<a class="tile guided-chapter" href="#chapter/${t.id}"><span class="eyebrow">${e(t.title.split(' · ')[0])}</span><h3>${e(t.title.split(' · ')[1])}</h3><p>${e(t.subtitle)}</p><div class="meter"><span style="width:${count/ls.length*100}%"></span></div><p class="small muted">${count} of ${ls.length} lessons explored →</p></a>`;}).join('')}</div>`;return;
 }
 const record=startGuided(p,lesson.id);persist();
 const example= ['promise','price','yield'].includes(lesson.id)?bondLessonExample(lesson.id):lesson.calculations.length?generate(lesson.calculations[0],100+guidedLessons.indexOf(lesson)*151):null;
 const extraMath=lesson.calculations.length?generate(lesson.calculations[0],1701+record.visits*997+guidedLessons.indexOf(lesson)*71):null;
 let mathRevealed=false,mathDraft='';
 const textToMatch=(lesson.context+' '+lesson.teaching+' '+lesson.conceptIds.map(id=>card(id)?.title).join(' ')).toLowerCase();
 let terms=[...(guidedTermLists[lesson.topic]||[]),...basicTermDefinitions].filter(([t])=>new RegExp('(^|[^a-z0-9])'+t.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^a-z0-9]|$)').test(textToMatch));
 if(!terms.length)terms=(guidedTermLists[lesson.topic]||[]).slice(0,4);
 const glossary=`<details class="term-help"><summary class="button">Explain key terms</summary><dl class="terms-box">${terms.map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></details>`;
 const references=()=>`<details class="guided-more"><summary>More detail and related concepts</summary>${lesson.conceptIds.map(id=>{const c=card(id);const src=data.sources[c.source];return `<article class="guided-reference"><h3>${e(c.title)}</h3><p class="small muted">${e(c.prompts[0])}</p><p>${e(c.answer)}</p><p class="small muted">${e(c.explanation)}</p>${c.numberNotes?`<p class="small">${e(c.numberNotes)}</p>`:``}${c.formula?`<div class="formula">${e(c.formula)}</div>${shortTermHelp(c.symbols)}`:''}<a class="small link" href="${e(src[1])}" target="_blank" rel="noopener noreferrer">${e(src[0])} ↗</a></article>`;}).join('')}${lesson.calculations.slice(1).map((key,i)=>`<details><summary>Another worked example: ${e(key.replaceAll('-',' '))}</summary>${renderNumberWork(generate(key,401+i*113),e)}</details>`).join('')}</details>`;
 function readingSection(s){return `<section class="reading-section"><h2>${e(s.title)}</h2><p>${e(s.text)}</p></section>`;}
 function instruction(){return `<section class="guided-teaching">${lesson.sections.slice(record.review?1:0).map(readingSection).join('')}${example?renderNumberWork(example,e):''}${lesson.id==='price'?`<details class="guided-explorer"><summary>Explore how required yield changes price</summary><label for="guided-yield">Required annual yield <output id="guided-rate">6.0% per year</output></label><input id="guided-yield" type="range" min="3" max="8" step="0.5" value="6"><p class="example-result"><span>Purchase price in dollars today</span><strong id="guided-bond-price">$973.27</strong></p><div id="guided-price-working">${renderNumberWork(bondLessonExample('price'),e,{withCalculator:false})}</div></details>`:''}</section>`;}
 function variation(){return extraMath?`<details class="guided-variation"><summary>Try one calculation variation (optional)</summary><p>${e(extraMath.prompt)}</p><dl class="example-inputs">${extraMath.givens.map(([t,v])=>`<div><dt>${e(t)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><div class="formula">${e(extraMath.formula)}</div>${shortTermHelp(extraMath.symbols)}${renderCalculator(`guided:${lesson.id}:${record.visits}`,{targetId:mathRevealed?'':'guided-number',answerUnit:extraMath.unit})}${mathRevealed?`<div class="feedback"><p>${e(mathDraft?isCorrect(parseNumber(mathDraft),extraMath)?'Your calculation matches.':'Compare your result with the steps below.':'Here are the calculation steps.')}</p></div>${renderNumberWork(extraMath,e,{withCalculator:false})}`:`<label for="guided-number">Your result (${e(extraMath.unit)})</label><input id="guided-number" type="text" inputmode="decimal" value="${e(mathDraft)}" placeholder="Enter your result, or use the calculator above"><div class="actions"><button id="guided-check-number">Check calculation</button><button id="guided-explain-number">Show the steps</button></div>`}</details>`:'';}
 function render(){
  root.innerHTML=warning+`<div class="guided-lesson"><a class="back" href="#chapter/${lesson.topic}">← ${e(topic(lesson.topic).title.split(' · ')[1])}</a><span class="eyebrow">${record.review?'A SHORT REVIEW':'GUIDED LESSON'}</span><h1>${e(lesson.title)}</h1><section class="guided-context"><span class="eyebrow">THE SITUATION</span><p>${e(lesson.context)}</p></section>${lesson.units?`<aside class="lesson-units"><strong>How to read the numbers</strong><p>${e(lesson.units)}</p></aside>`:''}${glossary}${record.review?`${readingSection(lesson.sections[0])}<details class="guided-refresher"><summary>Read the rest of the explanation and worked example</summary>${instruction()}</details>`:instruction()}<section class="guided-application"><span class="eyebrow">APPLY THE IDEA</span><h2>${e(lesson.question)}</h2>${lesson.options.map((o,i)=>`<button class="choice ${record.revealed&&i===lesson.correct?'correct':''}" data-guide-choice="${i}" ${record.revealed?'disabled':''}>${e(o)}</button>`).join('')}${record.revealed?`<div class="feedback" role="status"><p>${e(lesson.explanation)}</p></div>${variation()}<div class="actions guided-confidence"><button class="primary" data-guide-finish="clear">Clear · space the next review</button><button data-guide-finish="close">Needs another look</button></div>`:'<button class="textbutton" id="guide-walkthrough">Walk me through it</button>'}</section>${chapterConnections[lesson.topic]?.lessonId===lesson.id?renderConnections(lesson.topic,e,{lesson:true}):''}${references()}</div>`;
  root.querySelectorAll('[data-guide-choice]').forEach(b=>b.onclick=()=>{record.choice=Number(b.dataset.guideChoice);record.revealed=true;persist();render();});root.querySelector('#guide-walkthrough')?.addEventListener('click',()=>{record.choice=null;record.revealed=true;persist();render();});
  root.querySelectorAll('[data-guide-finish]').forEach(b=>b.onclick=()=>{finishGuided(p,lesson.id,b.dataset.guideFinish);persist();showFinished();});
  root.querySelector('#guided-number')?.addEventListener('input',ev=>mathDraft=ev.target.value);
  root.querySelector('#guided-check-number')?.addEventListener('click',()=>{if(parseNumber(mathDraft)===null){notify('Enter a number, or choose Show the steps.');return;}mathRevealed=true;render();root.querySelector('.guided-variation').open=true;});
  root.querySelector('#guided-explain-number')?.addEventListener('click',()=>{mathRevealed=true;render();root.querySelector('.guided-variation').open=true;});
  root.querySelector('#guided-yield')?.addEventListener('input',ev=>{const rate=Number(ev.target.value),y=rate/100,total=bondPrice(1000,50,y,3),base=bondLessonExample('price');const updated={...base,givens:base.givens.map(([t,v])=>[t,t==='Required annual yield'?rate.toFixed(1)+'% per year (chosen slider input)':v]),steps:['Coupon = $1,000 × 0.05 = $50; final payment = $1,000 + $50 = $1,050.',`Yield ${rate}% ÷ 100 = ${y}; gross discount factor = 1 + ${y} = ${(1+y).toFixed(3)}.`,...Array.from({length:3},(_,i)=>{const t=i+1,cf=t===3?1050:50;return `Year ${t}: $${cf} ÷ (1 + ${y})^${t} = $${(cf/(1+y)**t).toFixed(2)}.`;}),`Sum using full precision = $${total.toFixed(2)}.`],answerText:priceLabel(total)};root.querySelector('#guided-rate').textContent=rate.toFixed(1)+'% per year';root.querySelector('#guided-bond-price').textContent=priceLabel(total);root.querySelector('#guided-price-working').innerHTML=renderNumberWork(updated,e,{withCalculator:false});});
 }
 function showFinished(){const next=nextGuided(p);root.innerHTML=`<div class="study center"><span class="eyebrow">${lastSaveOk?'PROGRESS SAVED':'SESSION COMPLETE'}</span><h1>Lesson complete.</h1>${!lastSaveOk?'<p class="errorbanner" role="alert">This browser has not saved the lesson progress. You can keep reading, but this completion may be lost when you leave.</p>':''}<p class="muted">Your next spaced review is ${dateGuide(record.due)}.<br>You can stop here for today.</p><div class="actions"><a class="button primary" href="#today">Done for today</a>${next?`<button data-guide-start="${next.id}">Continue to another lesson</button>`:'<a class="button" href="#lessons">Browse the course</a>'}</div></div>`;bindStarts();}
 render();
}
